    this.options.forEach((option) => this._applyEnvPrefix(option));
    return this;
  }

  /**
   * @param {Option} option
   * @private
   */
  _applyEnvPrefix(option) {
    if (
      this._envPrefix === undefined ||
      option.envVar !== undefined ||
      option.negate
